// Plan:
// 1. Extract the two unsigned 32-bit integers from the input array.
// 2. Convert these integers to 64-bit signed integers.
// 3. Compute the XOR of these two integers to find differing bits.
// 4. Count the number of set bits (1s) in the XOR result.
// 5. Return the count as a JSON number.

use serde_json::Value;

pub fn solve(input: Value) -> Value {
    // Extract the two unsigned 32-bit integers from the input array
    let arr = input.as_array().unwrap();
    let a = arr[0].as_u64().unwrap() as i64;
    let b = arr[1].as_u64().unwrap() as i64;

    // Compute the XOR of the two integers
    let xor_result = a ^ b;

    // Count the number of set bits (1s) in the XOR result
    let differing_bits_count = xor_result.count_ones() as u64;

    // Return the count as a JSON number
    Value::Number(serde_json::Number::from(differing_bits_count))
}
